let ensureNotBlocked action memberId (library: Library) =
    if isBlocked memberId library then
        Error(MemberBlocked(memberId, owed memberId library, action))

let renew ports (copyId: string) : Result<Views.RenewView, LendingError> =
    commit ports (fun today library ->
        Loans.renew today (CopyId copyId) library
